                highestIntent,
                applyFrame,
                createArbiter,
                startActivitySensor,
                DEFAULT_CONFIG,
                mergeConfig,
                createConfigStore,
                INTENT_CFG_KEY,
                SETTINGS_NS,
                ALL_ANIMS,
                ANIMS,
                ANIM_BY_ID,
                ANIM_BY_NAME,
                animUrl,
                animName,
                normalizeAnimId,
                animFacingTransform,
                LOCALES,
                SettingsForm,
                SettingsCard,
                ActionPicker,
                WhalePet,
                // 交互增强
                clickZoneIndex,
                estimateVelocity,
                pickFrom,
                ANIM_FAIL_COOLDOWN_MS,
                failedAnims,
                DOUBLE_CLICK_MS,
                DOUBLE_ANIM,
                FOLLOW_CHANCE,
                INERTIA_MIN_SPEED,
                INERTIA_TAU,
                INERTIA_STOP_SPEED,
                BOUNCE_RESTITUTION,
                GROUND_FRICTION_TAU,
                FLING,
                FLING_START_SEC,
                characterCollisionBounds,
                TARGET_MOVE_ANIM,
                GREET_ANIM,
                WALK_ANIM,
                RUN_ANIM,
                BUILTIN_ASSET_REVISIONS,
                // 资源层
